// Acme palette, generated by Spring (someshks.com/spring).
// Headless: change a seed or the curve and call scale() to rebuild. No dependencies.
// Note: the system's contrast fixes (nudged text steps) are applied on top in tokens.css.

export const curve = { bezier: [0.42, 0, 1, 1], hueShift: 0, darkChroma: 0.78 };
export const ends = { light: [0.993, 0.24], dark: [0.165, 0.95] };
export const seeds = {
  primary: {
    hue: 154,
    chroma: 0.179,
    l: 0.55,
    bend: true,
  },
  neutral: {
    hue: 75,
    chroma: 0.00972,
    l: 0.62,
    bend: false,
  },
  danger: {
    hue: 25,
    chroma: 0.2,
    l: 0.55,
    bend: false,
  },
  warning: {
    hue: 70,
    chroma: 0.16,
    l: 0.82,
    bend: false,
  },
  success: {
    hue: 130,
    chroma: 0.15,
    l: 0.52,
    bend: false,
  },
  info: {
    hue: 245,
    chroma: 0.15,
    l: 0.52,
    bend: false,
  },
  green: {
    hue: 154.0261013804511,
    chroma: 0.13863306031578063,
    l: 0.5500050724257002,
    bend: false,
  },
  violet: {
    hue: 315.1650378705081,
    chroma: 0.17926821256738804,
    l: 0.7193310927671838,
    bend: false,
  },
};

const cubic = (a, b, t) =>
  3 * a * t * (1 - t) ** 2 + 3 * b * t ** 2 * (1 - t) + t ** 3;
export function ease([x1, y1, x2, y2], x) {
  let lo = 0,
    hi = 1;
  for (let i = 0; i < 30; i++) {
    const mid = (lo + hi) / 2;
    if (cubic(x1, x2, mid) < x) lo = mid;
    else hi = mid;
  }
  return cubic(y1, y2, (lo + hi) / 2);
}

function toLinear({ l, c, h }) {
  const r = (h * Math.PI) / 180,
    a = c * Math.cos(r),
    b = c * Math.sin(r);
  const L = (l + 0.3963377774 * a + 0.2158037573 * b) ** 3;
  const M = (l - 0.1055613458 * a - 0.0638541728 * b) ** 3;
  const S = (l - 0.0894841775 * a - 1.291485548 * b) ** 3;
  return [
    4.0767416621 * L - 3.3077115913 * M + 0.2309699292 * S,
    -1.2684380046 * L + 2.6097574011 * M - 0.3413193965 * S,
    -0.0041960863 * L - 0.7034186147 * M + 1.707614701 * S,
  ];
}
const inGamut = (c) => toLinear(c).every((v) => v >= -1e-4 && v <= 1 + 1e-4);
function fit(c) {
  if (inGamut(c)) return c;
  let lo = 0,
    hi = c.c;
  for (let i = 0; i < 24; i++) {
    const mid = (lo + hi) / 2;
    if (inGamut({ ...c, c: mid })) lo = mid;
    else hi = mid;
  }
  return { ...c, c: lo };
}
const gamma = (v) =>
  v <= 0.0031308 ? 12.92 * v : 1.055 * v ** (1 / 2.4) - 0.055;
export function hex(c) {
  return (
    "#" +
    toLinear(fit(c))
      .map((v) =>
        Math.round(Math.min(1, Math.max(0, gamma(v))) * 255)
          .toString(16)
          .padStart(2, "0"),
      )
      .join("")
  );
}

/** 12 steps, page to text, bent through the seed's lightness. mode: "light" | "dark". */
export function scale(
  { hue, chroma, l: target, bend = true },
  mode = "light",
  c = curve,
) {
  const [from, to] = ends[mode];
  const e = Array.from({ length: 12 }, (_, i) => ease(c.bezier, i / 11));
  const raw = e.map((y) => from + (to - from) * y);
  let k = 3;
  for (let s = 3; s <= 10; s++)
    if (Math.abs(raw[s - 1] - target) < Math.abs(raw[k - 1] - target)) k = s;
  const ek = e[k - 1];
  const lb = Math.min(
    Math.max(target, Math.min(from, to) + 0.02),
    Math.max(from, to) - 0.02,
  );
  const tk = (k - 1) / 11;
  return e.map((y, i) => {
    const t = i / 11;
    const l =
      i < k - 1
        ? from + (lb - from) * (ek ? y / ek : 0)
        : lb + (to - lb) * (ek < 1 ? (y - ek) / (1 - ek) : 0);
    const w = t < tk ? Math.max(tk, 0.35) : 0.55;
    const share = Math.max(t > tk ? 0.4 : 0.05, 1 - ((t - tk) / w) ** 2);
    return hex({
      l,
      c: chroma * share * (mode === "dark" ? (c.darkChroma ?? 1) : 1),
      h: (((hue + (bend ? c.hueShift : 0) * (t - tk)) % 360) + 360) % 360,
    });
  });
}
